import {CONFIG} from './shared/config.js?v=68';
import {rankFor} from './leveling.js?v=68';
export const SKILL_BRANCHES=CONFIG.progression.skills.branches;
export const SKILL_CAPS=CONFIG.progression.skills.caps;
export const SKILLS=Object.fromEntries(SKILL_BRANCHES.flatMap(b=>b.nodes.map(n=>[n.id,{...n,branch:b.id}])));
export const SKILL_LABELS={sprintSpeed:'Sprint speed',dodgeCost:'Dodge stamina saved',rollCost:'Roll stamina saved',staminaMax:'Stamina capacity',staminaRegen:'Stamina recovery',sprintDrain:'Sprint stamina saved',protection:'Damage protection',knockResistance:'Knockback resistance',blockStrength:'Guard protection',bleedResistance:'Bleed resistance',healing:'Potion healing',fireResistance:'Fire resistance',magicDamage:'Magic damage',arrowDamage:'Arrow damage',frostResistance:'Frost resistance'};
export function sanitizeSkills(raw){const input=new Set(Array.isArray(raw)?raw.filter(id=>Object.hasOwn(SKILLS,id)):[]),owned=[];for(const node of Object.values(SKILLS))if(input.has(node.id)&&node.requires.every(id=>owned.includes(id)))owned.push(node.id);return owned;}
const cache=new WeakMap();
export function skillBonuses(profile){if(!profile||typeof profile!=='object')return Object.fromEntries(Object.keys(SKILL_CAPS).map(k=>[k,0]));const signature=(profile.skills??[]).join('|'),old=cache.get(profile);if(old?.signature===signature)return old.value;const value=Object.fromEntries(Object.keys(SKILL_CAPS).map(k=>[k,0]));for(const id of sanitizeSkills(profile.skills))for(const [key,n]of Object.entries(SKILLS[id].bonuses))value[key]=Math.min(SKILL_CAPS[key],value[key]+n);cache.set(profile,{signature,value});return value;}
export function skillAccess(p,id){const node=Object.hasOwn(SKILLS,id)?SKILLS[id]:null;if(!node)return{ok:false,error:'Unknown skill'};if((p.skills??[]).includes(id))return{ok:false,error:'Already learned',owned:true};const level=rankFor(p.rating??0).level;if(level<node.level)return{ok:false,error:'Requires level '+node.level};const missing=node.requires.find(id=>!(p.skills??[]).includes(id));if(missing)return{ok:false,error:'Requires '+SKILLS[missing].name};if(p.coins<node.price)return{ok:false,error:'Need '+(node.price-p.coins).toLocaleString()+' more coins'};return{ok:true};}
export function buySkill(p,id){const result=skillAccess(p,id);if(!result.ok)return result;p.coins-=SKILLS[id].price;p.skills=sanitizeSkills([...(p.skills??[]),id]);return{ok:true,node:SKILLS[id]};}
export function purchaseAccess(p,kind,id){const level=CONFIG.progression.purchaseLevels[kind]?.[id]??1,current=rankFor(p.rating??0).level;return current>=level?{ok:true,level}:{ok:false,level,error:'Requires level '+level+' to buy'};}
export const skillSummary=bonuses=>Object.entries(bonuses).filter(([,n])=>n>0).map(([key,n])=>({key,label:SKILL_LABELS[key],percent:Math.round(n*1000)/10}));
